// PEN de Ciclo II en francés: las tablas de situaciones de `segundo.ts`, fila a fila, con
// la misma dificultad, imagen y orden. Los generadores con lógica son los mismos que en
// español y eligen el texto con `tx`. PEN2-T1 no está aquí por eso mismo.
import { generadorDeSituaciones } from "../../plantillas.ts";
import type { Generador, MapaGeneradores } from "../../tipos.ts";
import { objeto, porDificultad, type Fila } from "./comun.ts";
import { comoGeneradorMezcla, cuantosFaltan, elegirNecesidad, platoMasVariado, presupuestoImportante, queObjeto } from "./segundo.ts";

function situacionesFr(sub: string, filas: readonly Fila[]): Generador {
  return generadorDeSituaciones(
    sub,
    filas.map(([dificultad, enunciado, enunciadoFacil, correcta, distractores, pista, explicacion, imagen], i) => ({
      id: `fr-${sub}-s${i + 1}`,
      sub,
      dificultad,
      enunciado,
      enunciadoFacil,
      correcta,
      distractores,
      pista,
      explicacion,
      ...(imagen === undefined ? {} : { imagen }),
    })),
  );
}

